// client/src/api/rouletteApi.js

import axiosInstance from './axiosInstance'; // 👈 이제 파일을 찾을 수 있습니다!

// 1. 룰렛 돌리기
export const spinRoulette = async () => {
    try {
        const response = await axiosInstance.post('/roulette/spin'); // 룰렛 경로 사용
        return response.data; 
    } catch (error) {
        throw error.response?.data?.message || '룰렛 돌리기 실패'; 
    }
};

// 2. 사용자의 현재 포인트 조회
export const getUserPoints = async () => {
    try {
        // 포인트는 User 엔드포인트에서 가져오는 것이 자연스럽습니다.
        const response = await axiosInstance.get('/users/points'); 
        return response.data.points; 
    } catch (error) {
        throw error.response?.data?.message || '포인트 조회 실패';
    }
};
